SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- =====================================================================
-- Étiquettes simples des fiches visibles des élèves (`plants.usage_label`)
-- (chantier collège de novembre 2026, flux D5).
--
-- FICHIER GÉNÉRÉ par scripts/college-2026-11/build-D5-migration.js à partir de
-- data/college-2026-11/D5/*.json : ne pas modifier à la main.
--
-- Une étiquette par fiche hors `entity_kind = ressource` : article indéfini + nom
-- commun courant + précision (« une araignée sauteuse »), 40 caractères au plus.
--
-- Gardes : clé naturelle (`plants.name` + `scientific_name` via <=>) ; une étiquette
-- posée dans l'application n'est jamais écrasée (`usage_label IS NULL` attendu) ;
-- une fiche absente (base fraîche) est sautée sans erreur. Idempotent (rejouable deux
-- fois), aucun trigger, aucun DEFINER, aucune table `gl_*`, aucune donnée personnelle.
-- =====================================================================

